// Pseudocode: Idempotent deduplication framework
function processEvent(event) {
  const compositeKey = `${event.tenantId}|${event.deviceId}|${event.timestamp}`;

  // Check for existing record to ensure idempotency
  const existingRecord = await dynamoDB.getItem({
    Key: { id: compositeKey }
  });

  if (!existingRecord.Item) {
    // Process and store new event
    await storeEvent(event);
  }
}
```

